fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Work in i32 to avoid overflow from expressions like 2*a - f.
    let a = a as i32;
    let b = b as i32;
    let f = f as i32;
    let k = k as i32;

    let to_station_from_start = f;
    let to_end_from_station = a - f;

    // Basic reachability: must be able to reach the station from either side.
    if b < to_station_from_start || b < to_end_from_station {
        return -1;
    }

    // Special-case: exactly one journey.
    // Feasible if we can reach the end directly, or reach the station (then refuel) to finish.
    if k == 1 {
        if b >= a {
            return 0; // no refuel needed
        } else {
            // Given earlier checks, b >= f and b >= a-f, so one refuel at station works.
            return 1;
        }
    }

    // For k > 1, the strictest required segment is starting from the station and needing:
    // go to the far endpoint and come back to the station before any endpoint refuel is allowed.
    // That distance is (a - f) + a = 2a - f.
    if b < 2 * a - f {
        return -1;
    }

    // With these constraints satisfied, at least one station refuel is required at some point.
    // Reason: endpoints never refuel; after each trip, fuel is strictly reduced. With k>1,
    // you must refuel at station to continue.
    1
}